import java.io.*;
import java.util.StringTokenizer;

public class Main {
    static long[] sum = new long[105];
    static long[] pw = new long[105];

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        long w = in.nextLong();
        long m = in.nextLong();

        long p = 1;
        int mx = 0;
        for (int i = 0; i < 100; ++i) {
            sum[i + 1] = p + sum[i];
            pw[i] = p;
            p *= w;
            if (p > 1L << 40) {
                mx = i;
                break;
            }
        }

        out.println(can(0, m, mx) ? "YES" : "NO");
        out.close();
    }

    static boolean can(long cur, long target, int pos) {
        if (cur == target) return true;
        long remaining = sum[pos + 1];
        long next = pw[pos];
        if (cur - remaining > target) return false;
        if (cur + remaining < target) return false;
        if (cur + sum[pos] < target) {
            return can(cur + next, target, pos - 1);
        } else if (cur - sum[pos] > target) {
            return can(cur - next, target, pos - 1);
        } else {
            return can(cur, target, pos - 1);
        }
    }

    static class InputReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer = new StringTokenizer("");

        public InputReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (!tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return tokenizer.nextToken();
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}
